def profile(
    family: str,
    level: str,
    core: str,
    flow: str,
    decisions: str,
    metrics: str,
    scenario: str,
    project: str,
    sources: str,
    adjacent: str,
) -> dict[str, object]:
    """Convierte una notación compacta en datos fáciles de validar y renderizar."""

    part_map: dict[str, list[str]] = {}
    for item in core.split(";"):
        part, ids = item.split(":", 1)
        part_map[part] = [f"SE-{int(value):03d}" for value in ids.split(",")]
    return {
        "family": family,
        "level": level,
        "core": part_map,
        "flow": flow.split("|"),
        "decisions": [tuple(item.split("|")) for item in decisions.split(";")],
        "metrics": [tuple(item.split("|")) for item in metrics.split(";")],
        "scenario": tuple(scenario.split("|")),
        "project": tuple(project.split("|")),
        "sources": sources.split("|"),
        "adjacent": adjacent.split("|"),
    }


